// Gerado a partir de data/prayers.json e data/rosary.json (somente pt)
window.ORA_DATA = {"prayers": [{"id": "pai-nosso", "title": "Pai Nosso", "text": "Pai nosso, que estais nos céus,\nsantificado seja o Vosso nome;\nvenha a nós o Vosso reino,\nseja feita a Vossa vontade,\nassim na terra como no céu.\n\nO pão nosso de cada dia nos dai hoje;\nperdoai-nos as nossas ofensas,\nassim como nós perdoamos\na quem nos tem ofendido;\ne não nos deixeis cair em tentação,\nmas livrai-nos do mal. Amém."}, {"id": "ave-maria", "title": "Ave Maria", "text": "Ave Maria, cheia de graça,\no Senhor é convosco,\nbendita sois vós entre as mulheres\ne bendito é o fruto do vosso ventre, Jesus.\n\nSanta Maria, Mãe de Deus,\nrogai por nós, pecadores,\nagora e na hora da nossa morte. Amém."}, {"id": "gloria", "title": "Glória ao Pai", "text": "Glória ao Pai, e ao Filho e ao Espírito Santo.\nComo era no princípio, agora e sempre. Amém."}, {"id": "salve-rainha", "title": "Salve Rainha", "text": "Salve, Rainha, Mãe de misericórdia,\nvida, doçura e esperança nossa, salve!\nA vós bradamos, os degredados filhos de Eva;\na vós suspiramos, gemendo e chorando\nneste vale de lágrimas.\n\nEia, pois, advogada nossa,\nesses vossos olhos misericordiosos a nós volvei;\ne depois deste desterro nos mostrai Jesus,\nbendito fruto do vosso ventre,\nó clemente, ó piedosa,\nó doce sempre Virgem Maria.\n\nV. Rogai por nós, santa Mãe de Deus.\nR. Para que sejamos dignos das promessas de Cristo."}, {"id": "credo", "title": "Credo", "text": "Creio em Deus Pai Todo-Poderoso,\nCriador do céu e da terra;\ne em Jesus Cristo, seu único Filho, nosso Senhor;\nque foi concebido pelo poder do Espírito Santo;\nnasceu da Virgem Maria,\npadeceu sob Pôncio Pilatos,\nfoi crucificado, morto e sepultado;\ndesceu à mansão dos mortos;\nressuscitou ao terceiro dia;\nsubiu aos céus,\nestá sentado à direita de Deus Pai Todo-Poderoso,\ndonde há de vir a julgar os vivos e os mortos.\n\nCreio no Espírito Santo,\nna Santa Igreja Católica,\nna comunhão dos Santos,\nna remissão dos pecados,\nna ressurreição da carne,\nna vida eterna. Amém."}, {"id": "ato-contricao", "title": "Ato de Contrição", "text": "Meu Deus, eu me arrependo de todo o coração de vos ter ofendido,\nporque sois tão bom e amável.\nPrometo, com a vossa graça,\nesforçar-me para não mais pecar.\nMeu Jesus, misericórdia!"}, {"id": "sao-miguel", "title": "São Miguel Arcanjo", "text": "São Miguel Arcanjo, defendei-nos no combate,\nsede o nosso refúgio contra as maldades e ciladas do demônio.\nOrdene-lhe Deus, instantemente o pedimos,\ne vós, príncipe da milícia celeste,\npela virtude divina,\nprecipitai no inferno a satanás e a todos os espíritos malignos,\nque andam pelo mundo para perder as almas. Amém."}, {"id": "angelus", "title": "Angelus", "text": "V. O Anjo do Senhor anunciou a Maria.\nR. E ela concebeu do Espírito Santo.\nAve Maria...\n\nV. Eis a escrava do Senhor.\nR. Faça-se em mim segundo a vossa palavra.\nAve Maria...\n\nV. E o Verbo se fez carne.\nR. E habitou entre nós.\nAve Maria...\n\nV. Rogai por nós, santa Mãe de Deus.\nR. Para que sejamos dignos das promessas de Cristo.\n\nOremos: Infundi, Senhor, nós Vos pedimos,\na Vossa graça em nossas almas,\npara que nós, que pela anunciação do Anjo\nconhecemos a Encarnação de Jesus Cristo, Vosso Filho,\npela Sua paixão e cruz,\nsejamos conduzidos à glória da ressurreição.\nPelo mesmo Cristo, Senhor nosso. Amém."}, {"id": "sao-carlo-acutis", "title": "São Carlo Acutis", "text": "Deus eterno e todo-poderoso, que nos criou à Sua imagem\ne nos mandou buscar tudo o que é bom, verdadeiro e belo,\nespecialmente na pessoa divina do Teu Filho unigênito,\nNosso Senhor Jesus Cristo,\nconcedei que, através da intercessão do Bem-Aventurado Carlo Acutis\ndurante nossas viagens pela internet,\ndirijamos nossas mãos e nossos olhos somente àquilo que é agradável a Vós\ne tratemos com caridade e paciência todas aquelas almas que encontrarmos.\nPor Cristo, Nosso Senhor. Amém."}, {"id": "vinde-espirito-santo", "title": "Vinde Espírito Santo", "text": "Vinde, Espírito Santo,\nenchei os corações dos vossos fiéis\ne acendei neles o fogo do Vosso amor.\n\nEnviai o Vosso Espírito e tudo será criado,\ne renovareis a face da terra.\n\nOremos: Ó Deus, que instruístes os corações dos vossos fiéis\ncom a luz do Espírito Santo,\nfazei que apreciemos retamente todas as coisas\nsegundo o mesmo Espírito\ne gozemos sempre da Sua consolação.\nPor Cristo Senhor Nosso. Amém."}, {"id": "oferecimento-obras", "title": "Oferecimento das Obras", "text": "Ofereço-vos, ó meu Deus, em união com o Santíssimo Coração de Jesus,\npelas mãos de Maria Imaculada,\nas orações, obras, sofrimentos e alegrias deste dia,\nem reparação de nossas ofensas\ne por todas as intenções pelas quais o mesmo Divino Coração\nestá continuamente intercedendo e sacrificando-se em nossos altares.\nEu vo-las ofereço de modo particular pelas intenções do Santo Padre, o Papa,\nneste mês e neste dia. Amém."}, {"id": "sao-tomas-estudo", "title": "Oração para o Estudo", "text": "Criador Inefável, Vós que sois a verdadeira fonte da luz e da sabedoria,\ndignai-vos infundir sobre as trevas da minha inteligência\num raio da vossa claridade,\nafastando de mim a dupla escuridão em que nasci:\no pecado e a ignorância.\n\nVós, que tornais eloquente a língua das crianças,\nmodelai a minha palavra e derramai nos meus lábios a graça da vossa bênção.\nDai-me agudeza para entender, capacidade para reter,\nmétodo e facilidade para aprender,\nsutileza para interpretar e graça abundante para falar.\n\nInspirai o começo, dirigi o meio e coroai o fim.\nVós que sois verdadeiro Deus e verdadeiro Homem,\ne que viveis e reinais pelos séculos dos séculos. Amém."}, {"id": "trabalho-sao-jose", "title": "Oferecimento do Trabalho", "text": "Glorioso São José, modelo de todos os que se dedicam ao trabalho,\nobtende-me a graça de trabalhar com espírito de penitência,\npara expiação de meus numerosos pecados;\nde trabalhar com consciência, pondo o culto do dever acima de minhas inclinações;\nde trabalhar com recolhimento e alegria,\nolhando como uma honra empregar e desenvolver pelo trabalho\nos dons recebidos de Deus.\n\nTrabalhar com ordem, paz, moderação e paciência,\nsem nunca recuar perante o cansaço e as dificuldades;\ntrabalhar sobretudo com pureza de intenção e com desapego de mim mesmo,\ntendo sempre diante dos olhos a morte e a conta que deverei dar do tempo perdido,\ndos talentos inutilizados, do bem omitido\ne da vã complacência nos sucessos, tão funesta à obra de Deus.\nTudo por Jesus, tudo por Maria, tudo à vossa imitação, ó Patriarca São José!\nTal será a minha divisa na vida e na morte. Amém."}, {"id": "fica-senhor-comigo", "title": "Fica Senhor Comigo", "text": "Fica Senhor comigo, pois preciso da tua presença para não te esquecer.\nSabes quão facilmente posso te abandonar.\nFica Senhor comigo, porque sou fraco e preciso da tua força para não cair.\nFica Senhor comigo, porque és minha vida, e sem ti perco o fervor.\nFica Senhor comigo, porque és minha luz, e sem ti reina a escuridão.\nFica Senhor comigo, para me mostrar tua vontade.\n\nFica Senhor comigo, para que ouça tua voz e te siga.\nFica Senhor comigo, pois desejo amar-te e permanecer sempre em tua companhia.\nFica Senhor comigo, se queres que te seja fiel.\nFica Senhor comigo, porque, por mais pobre que seja minha alma, quero que se transforme num lugar de consolação para ti, um ninho de amor.\n\nFica comigo, Jesus, pois se faz tarde e o dia chega ao fim; a vida passa, e a morte, o julgamento e a eternidade se aproximam. Preciso de ti para renovar minhas energias e não parar no caminho. Está ficando tarde, a morte avança e eu tenho medo da escuridão, das tentações, da falta de fé, da cruz, das tristezas. Oh, quanto preciso de ti, meu Jesus, nesta noite de exílio.\n\nFica comigo nesta noite, Jesus, pois ao longo da vida, com todos os seus perigos, eu preciso de ti. Faze, Senhor, que te reconheça como te reconheceram teus discípulos ao partir do pão, a fim de que a Comunhão Eucarística seja a luz a dissipar a escuridão, a força a me sustentar, a única alegria do meu coração.\n\nFica comigo, Senhor, porque na hora da morte quero estar unido a ti, se não pela Comunhão, ao menos pela graça e pelo amor.\n\nFica comigo, Jesus. Não peço consolações divinas, porque não as mereço, mas apenas o presente da tua presença, ah, isso sim te suplico!\n\nFica Senhor comigo, pois é só a ti que procuro, teu amor, tua graça, tua vontade, teu coração, teu Espírito, porque te amo, e a única recompensa que te peço é poder amar-te sempre mais. Com este amor resoluto desejo amar-te de todo o coração enquanto estiver na terra, para continuar a te amar perfeitamente por toda a eternidade. Amém.\n\nSão Padre Pio, rogai por nós!"}, {"id": "suplica-anjos", "title": "Súplica aos Santos Anjos", "text": "Deus uno e trino, onipotente e eterno! Antes de suplicarmos aos vossos servos, os Santos Anjos, prostramo-nos diante de vós e vos adoramos, Pai, Filho e Espírito Santo! Bendito e louvado sejais por toda a eternidade! E que todos os anjos e homens, por vós criados, vos adorem, vos amem e vos sirvam, ó Deus santo, Deus forte, Deus imortal!\n— E vós, Maria, Rainha de todos os anjos, aceitai benigna as súplicas dirigidas aos vossos servos e apresentai-as junto do trono do Altíssimo — vós que sois a onipotência suplicante e medianeira das graças — a fim de obtermos graça, salvação e auxílio. Amém. \n\nPoderosos Santos Anjos, que por Deus nos fostes concedidos para nossa proteção e auxílio, em nome da Santíssima Trindade nós vos suplicamos:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome do Preciosíssimo Sangue de Nosso Senhor Jesus Cristo:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pelo poderosíssimo nome de Jesus:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos por todas as chagas de Nosso Senhor Jesus Cristo:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos por todos os martírios de Nosso Senhor Jesus Cristo:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pela Palavra santa de Deus:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pelo Coração de Nosso Senhor Jesus Cristo:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome do amor que Deus tem por nós, pobres:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome da fidelidade de Deus por nós, pobres:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome da misericórdia de Deus por nós, pobres:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome de Maria, Mãe de Deus e nossa Mãe:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome de Maria, Rainha do Céu e da terra:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos em nome de Maria, vossa Rainha e Senhora:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pela vossa própria bem-aventurança:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pela vossa própria fidelidade:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos pela vossa luta na defesa do Reino de Deus:\n— Vinde depressa, socorrei-nos! \n\nNós vos suplicamos:\n— Protegei-nos com o vosso escudo! \n\nNós vos suplicamos:\n— Defendei-nos com a vossa espada! \n\nNós vos suplicamos:\n— Iluminai-nos com a vossa luz! \n\nNós vos suplicamos:\n— Salvai-nos sob o manto protetor de Maria! \n\nNós vos suplicamos:\n— Guardai-nos no Coração de Maria! \n\nNós vos suplicamos:\n— Confiai-nos às mãos de Maria! \n\nNós vos suplicamos:\n— Mostrai-nos o caminho que conduz à Porta da Vida: o Coração aberto de Nosso Senhor! \n\nNós vos suplicamos:\n— Guiai-nos com segurança à Casa do Pai celestial! \n\nTodos vós, nove coros dos espíritos bem-aventurados:\n— Vinde depressa, socorrei-nos! \n\nVós, nossos companheiros especiais, a nós dados por Deus:\n— Vinde depressa, socorrei-nos! \n\nInsistentemente vos suplicamos:\n— Vinde depressa, socorrei-nos! \n\nO Sangue Preciosíssimo de Nosso Senhor e Rei foi derramado por nós, pobres.\n— Insistentemente vos suplicamos: vinde depressa, socorrei-nos! \n\nO Coração de Nosso Senhor e Rei bate por amor de nós, pobres.\n— Insistentemente vos  suplicamos: vinde depressa, socorrei-nos! \n\nO Coração Imaculado de Maria, Virgem puríssima e vossa Rainha, bate por amor de nós pobres.\n— Insistentemente vos suplicamos: vinde depressa, socorrei-nos! \n\nSão Miguel Arcanjo, vós, príncipe dos exércitos celestes, vencedor do dragão infernal, recebestes de Deus força e poder para aniquilar, pela humildade, a soberba dos poderes das trevas.\n— Nós vos suplicamos que nos ajudeis a ter uma verdadeira humildade de coração, uma fidelidade inabalável no cumprimento contínuo da vontade de Deus e a fortaleza no sofrimento e na penúria. Socorrei-nos para subsistirmos perante o tribunal de Deus! \n\nSão Gabriel Arcanjo, vós, Anjo da Encarnação, mensageiro fiel de Deus, abri os nossos ouvidos também às suaves exortações e chamadas do Coração amoroso de Nosso Senhor.\n— Nós vos suplicamos que fiqueis sempre diante do nosso olhar para compreendermos bem a palavra de Deus, a seguirmos e lhe obedecermos e, assim, realizarmos aquilo que Deus quer de nós. Ajudai-nos a estar sempre disponíveis e vigilantes, de modo a que o Senhor, quando vier, não nos encontre dormindo! \n\nSão Rafael Arcanjo, vós, flecha de amor e remédio do amor de Deus,\n— nós vos suplicamos, feri o nosso coração com o amor ardente de Deus e nunca deixeis que esta ferida sare, para que, também no dia a dia, permaneçamos sempre no caminho do amor e tudo vençamos através do amor!\n\nSocorrei-nos, vós, nossos irmãos grandes e santos, que conosco servis diante de Deus!\n— Defendei-nos de nós próprios, da nossa covardia e tibieza, do nosso egoísmo e avareza, da nossa inveja e desconfiança, da nossa avidez de fartura, bem-estar e estima pública. \n\nDesatai em nós as algemas do pecado e do apego às coisas terrenas. Tirai dos nossos olhos as vendas que nós mesmos nos pusemos para não precisarmos ver a miséria ao nosso redor e permanecermos, assim, sossegados numa contemplação e compaixão de nós mesmos.\n— Cravai no nosso coração o aguilhão da santa inquietude por Deus, para que não cessemos de procurá-lo com ânsia, contrição e amor.\n\nContemplai o Sangue de Nosso Senhor, derramado por nossa causa!\n— Contemplai as lágrimas da vossa Rainha, choradas por nossa causa! \n\nContemplai em nós a imagem de Deus, que Ele por amor imprimiu na nossa alma e agora está desfigurada por nossos pecados!\n— Auxiliai-nos a conhecer Deus, adorá-lo, amá-lo e servi-lo! \n\nAuxiliai-nos na luta contra os poderes das trevas que disfarçadamente nos envolvem e afligem.\n— Auxiliai-nos para que nenhum de nós se perca e, um dia, nos reunamos todos, jubilosos, na eterna bem-aventurança. Amém. \n\nComo complemento a essas súplicas, pode-se invocar durante o dia, muitas vezes, os Santos Anjos: \n\nSão Miguel, assisti-nos com os vossos Anjos, ajudai-nos e rogai por nós! \nSão Gabriel, assisti-nos com os vossos Anjos, ajudai-nos e rogai por nós! \nSão Rafael, assisti-nos com os vossos Anjos, ajudai-nos e rogai por nós!"}, {"id": "sao-bento", "title": "São Bento", "text": "A Cruz Sagrada seja a minha luz,\nnão seja o dragão o meu guia.\nAfastate-te, satanás!\nNão me aconselhes coisas vãs.\nÉ mau o que tu me ofereces,\nbebe tu mesmo os teus venenos!"}], "mysteries": {"gozosos": ["A Anunciação do Anjo a Nossa Senhora", "A Visitação de Nossa Senhora a Santa Isabel", "O Nascimento de Jesus", "A Apresentação de Jesus no Templo", "A Perda e o Encontro de Jesus no Templo"], "dolorosos": ["A Agonia de Jesus no Horto", "A Flagelação de Jesus", "A Coroação de Espinhos", "Jesus carrega a Cruz", "A Crucificação e Morte de Jesus"], "gloriosos": ["A Ressurreição de Jesus", "A Ascensão de Jesus ao Céu", "A Vinda do Espírito Santo", "A Assunção de Nossa Senhora", "A Coroação de Nossa Senhora"], "luminosos": ["O Batismo de Jesus no Jordão", "A Auto-revelação de Jesus nas Bodas de Caná", "O Anúncio do Reino de Deus", "A Transfiguração de Jesus", "A Instituição da Eucaristia"]}, "extra": {"sinal-cruz": "Em nome do Pai, e do Filho, e do Espírito Santo. Amém.", "fatima": "Ó meu Jesus, perdoai-nos, livrai-nos do fogo do inferno, levai as almas todas para o Céu, e socorrei principalmente as que mais precisarem.", "pai-eterno": "Eterno Pai, eu Vos ofereço o Corpo e Sangue, Alma e Divindade de Vosso diletíssimo Filho, Nosso Senhor Jesus Cristo, em expiação dos nossos pecados e dos do mundo inteiro.", "dolorosa-paixao": "Pela Sua dolorosa Paixão, tende misericórdia de nós e do mundo inteiro.", "santo-deus": "Deus Santo, Deus Forte, Deus Imortal, tende piedade de nós e do mundo inteiro."}};
